import { useState, type FormEvent } from 'react';
import {
  JxInputField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = EMAIL_PATTERN.test(email);
  const emailError = emailTouched && !emailValid ? 'Похоже, это не почта. Проверьте формат адреса.' : undefined;

  const canSubmit = emailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)', maxWidth: 420 }}>
      {submitted && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-r-sm)' }}>
            <span>Мы отправили приглашение на {email}.</span>
            <JxButton
              variant="ghost"
              size="sm"
              iconOnly
              aria-label="Закрыть сообщение"
              onClick={() => setSubmitted(false)}
            >
              ×
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-lg)' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="На этот адрес придёт приглашение в команду"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div>
          <JxButton type="submit" variant="primary" disabled={!canSubmit}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

